#!/bin/bash
#SBATCH -J {JOB_NAME}
#SBATCH -A {ACCOUNT}
#SBATCH -t {TIME}
#SBATCH --mem-per-cpu={MEMORY_VALUE}
#SBATCH -n {PROCESSOR_NUMBER}
#SBATCH -N {NODES}
#SBATCH -e /work/scratch/as12vapa/{PROJECT_NAME}/{FOLDER_NAME}/%x.err.%j
#SBATCH -o /work/scratch/as12vapa/{PROJECT_NAME}/{FOLDER_NAME}/%x.out.%j
#SBATCH --mail-type=End
#SBATCH -C {CONSTRAINT}
#SBATCH --exclude={EXCLUDE}

# ------------------------------------------------------------------
# KLAIM 2025 revision 2 -- 3D job, generated by 02_create_jobs.sh
# ------------------------------------------------------------------
working_folder_name="{FOLDER_NAME}"
working_directory="$HPC_SCRATCH/{PROJECT_NAME}/$working_folder_name"
container="$HOME/dolfinx_alex/alex-dolfinx.sif"
bindpath="$HOME/dolfinx_alex/shared:/home,$working_directory:/work"
# private JIT cache per job: many jobs compiling the same forms into the shared $HOME/.cache/fenics at the
# same time make dolfinx fail with "Failed just-in-time compilation of form: Compilation failed on root node"
export XDG_CACHE_HOME="$working_directory/.cache"
export APPTAINERENV_XDG_CACHE_HOME="$XDG_CACHE_HOME"
mkdir -p "$XDG_CACHE_HOME"
# OpenBLAS 0.3.20 in the container picks the "Cooperlake" kernel on Sapphire Rapids (i02 nodes, Xeon 8470Q) and computes
# wrong results (MUMPS INFO(1)=-10, NO CONVERGENCE in the first step, NaN). Harmless on i01. Must be set before every
# apptainer call; APPTAINERENV_ is what reaches the container. Ref: HRZ, OpenBLAS_SPR_Knoten_20260905.pdf
export OPENBLAS_CORETYPE="${OPENBLAS_CORETYPE:-SkylakeX}"
export APPTAINERENV_OPENBLAS_CORETYPE="${APPTAINERENV_OPENBLAS_CORETYPE:-$OPENBLAS_CORETYPE}"
# optional per case (cases list, last column): dt grows again when Newton converges in < NEWTON_MIN_ITERS iterations
# (alex/solution.py default 4; with exactly 4 iterations per step dt stays frozen after a cut-back, see CLAUDE.md 2026-10-19)
NEWTON_MIN_ITERS_CASE="{NEWTON_MIN_ITERS}"
if [ -n "$NEWTON_MIN_ITERS_CASE" ]; then
    export NEWTON_MIN_ITERS="$NEWTON_MIN_ITERS_CASE"
    export APPTAINERENV_NEWTON_MIN_ITERS="$NEWTON_MIN_ITERS_CASE"
    echo "[$(date)] NEWTON_MIN_ITERS=$NEWTON_MIN_ITERS"
fi

WSTEG={WSTEG}
MATERIAL="{MATERIAL}"
GC_MICRO_PARAM={GC_MICRO_PARAM}
SIG_Y={SIG_Y}
HARD={HARD}
EMBEDDING="{EMBEDDING}"
CRACK_FACTOR={CRACK_FACTOR}
GEOMETRY="{GEOMETRY}"

NL_EFFECTIVE={NL_EFFECTIVE}
NL_FRACTURE={NL_FRACTURE}
NHOLES={NHOLES}
H_BAND="{H_BAND}"     # fixed element size in the crack band (mesh_fracture_adaptive.py --h_band); empty = old rule L/NL/n_ref
DHOLE={DHOLE}
MESH_FILE="{MESH_FILE}"
LAM_MICRO_PARAM={LAM_MICRO_PARAM}
MUE_MICRO_PARAM={MUE_MICRO_PARAM}
EPS_PARAM={EPS_PARAM}
ELEMENT_ORDER={ELEMENT_ORDER}
BETA={BETA}
ETA={ETA}
MOB={MOB}
SIG_Y_EMBEDDING={SIG_Y_EMBEDDING}
BC_MODULI="{BC_MODULI}"
K_BC_RULE="{K_BC_RULE}"
E_BC={E_BC}
NU_BC={NU_BC}
STOP_FRACTION={STOP_FRACTION}
POSTPROCESSING_INTERVAL={POSTPROCESSING_INTERVAL}
EVENT_SNAPSHOTS={EVENT_SNAPSHOTS}

LCRACK=$(awk "BEGIN {print $CRACK_FACTOR * ($WSTEG + $DHOLE)}")
echo "[$(date)] job $SLURM_JOB_ID case $working_folder_name: wsteg=$WSTEG material=$MATERIAL gc=$GC_MICRO_PARAM sig_y=$SIG_Y hard=$HARD embedding=$EMBEDDING lcrack=$LCRACK geometry=$GEOMETRY"
cd $HPC_SCRATCH

# restart after a timeout (RESTART_NACH_TIMEOUT.md): run_simulation.py --restart auto continues from
# run_simulation_checkpoint.h5 (or the last field output of runs started before the checkpoint code); without such data
# it starts fresh as before. RESTART_MODE=no sbatch job_script.sh forces a fresh start. CHECKPOINT_MINUTES = wall-time
# interval of the checkpoints. With restart data the preparation steps (meshes, homogenization) are skipped.
RESTART_MODE="${RESTART_MODE:-auto}"
CHECKPOINT_MINUTES="${CHECKPOINT_MINUTES:-30}"
HAVE_RESTART_DATA=0
if [ "$RESTART_MODE" != "no" ] && [ -f "$working_directory/$MESH_FILE" ] && grep -q "^mue_effective=" "$working_directory/parameters.txt" 2>/dev/null; then
    if [ -f "$working_directory/run_simulation_checkpoint.h5" ] || grep -qv "^#" "$working_directory/run_simulation_graphs.txt" 2>/dev/null; then
        HAVE_RESTART_DATA=1
    fi
fi
echo "[$(date)] RESTART_MODE=$RESTART_MODE CHECKPOINT_MINUTES=$CHECKPOINT_MINUTES restart data: $HAVE_RESTART_DATA"

if [ "$HAVE_RESTART_DATA" -eq 1 ]; then
echo "[$(date)] restart: mesh and parameters.txt exist, preparation steps skipped"
else
set -e
if [ "$GEOMETRY" = "porous" ]; then
echo "[$(date)] effective stiffness mesh"
srun -n 1 apptainer exec --bind $bindpath $container python3 $working_directory/mesh_effective_stiffness.py \
    --dhole "$DHOLE" --wsteg "$WSTEG" --NL "$NL_EFFECTIVE"
echo "[$(date)] effective stiffness"
srun -n 1 apptainer exec --bind $bindpath $container python3 $working_directory/run_effective_stiffness.py \
    --lam_micro_param "$LAM_MICRO_PARAM" --mue_micro_param "$MUE_MICRO_PARAM"
else
echo "[$(date)] no pores ($GEOMETRY): effective stiffness = micro stiffness, no homogenization"
printf "lam_effective=%s\nmue_effective=%s\n" "$LAM_MICRO_PARAM" "$MUE_MICRO_PARAM" >> $working_directory/parameters.txt
fi
if [ -f "$working_directory/premesh/mesh_fracture_adaptive.xdmf" ]; then
# 2026-10-26: mesh generated and inspected beforehand (6x3x2 series), copied into premesh/ -> use exactly this mesh
echo "[$(date)] fracture mesh: using the provided mesh in premesh/ (not regenerated)"
cp "$working_directory/premesh/domain_mesh.msh" "$working_directory/premesh/mesh_fracture_adaptive.xdmf" \
   "$working_directory/premesh/mesh_fracture_adaptive.h5" "$working_directory/"
cat "$working_directory/premesh/mesh_parameters.txt" >> "$working_directory/parameters.txt"
else
echo "[$(date)] fracture mesh"
srun -n 1 apptainer exec --bind $bindpath $container python3 $working_directory/mesh_fracture_adaptive.py \
    --Nholes "$NHOLES" --dhole "$DHOLE" --wsteg "$WSTEG" --NL "$NL_FRACTURE" --geometry "$GEOMETRY" ${H_BAND:+--h_band "$H_BAND"}
fi
echo "[$(date)] mesh info"
srun -n 1 apptainer exec --bind $bindpath $container python3 $working_directory/get_mesh_info.py --mesh_file "$MESH_FILE" \
    || echo "[$(date)] get_mesh_info failed (non-fatal: edge-length statistics only)"
set +e
fi

echo "[$(date)] fracture simulation"
srun -n {PROCESSOR_NUMBER} apptainer exec --bind $bindpath $container python3 $working_directory/run_simulation.py \
    --mesh_file "$MESH_FILE" \
    --in_crack_length "$LCRACK" \
    --lam_micro_param "$LAM_MICRO_PARAM" \
    --mue_micro_param "$MUE_MICRO_PARAM" \
    --gc_micro_param "$GC_MICRO_PARAM" \
    --eps_param "$EPS_PARAM" \
    --element_order "$ELEMENT_ORDER" \
    --material "$MATERIAL" \
    --sig_y "$SIG_Y" \
    --hard "$HARD" \
    --sig_y_embedding "$SIG_Y_EMBEDDING" \
    --beta "$BETA" \
    --eta "$ETA" \
    --mob "$MOB" \
    --embedding "$EMBEDDING" \
    --bc_moduli "$BC_MODULI" \
    --K_bc_rule "$K_BC_RULE" \
    --E_bc "$E_BC" \
    --nu_bc "$NU_BC" \
    --stop_fraction "$STOP_FRACTION" \
    --postprocessing_interval "$POSTPROCESSING_INTERVAL" \
    --event_snapshots "$EVENT_SNAPSHOTS" \
    --restart "$RESTART_MODE" \
    --checkpoint_minutes "$CHECKPOINT_MINUTES"
EXITCODE=$?
echo "[$(date)] finished with exit code $EXITCODE"
exit $EXITCODE
